using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class WeaponRebuild {
 [Serializable]public class Spec{public string id,family,tier,name;}
 [Serializable]public class Input{public Spec[] weapons;}
 static Camera camera;static Material material;static System.Text.StringBuilder report=new System.Text.StringBuilder();
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);}
 static Bounds BoundsOf(GameObject obj){bool first=true;var bounds=new Bounds();foreach(var s in obj.GetComponentsInChildren<SkinnedMeshRenderer>().Where(x=>x.name=="Weapon_LOD0")){var mesh=new Mesh();s.BakeMesh(mesh);foreach(var v in mesh.vertices){var p=obj.transform.InverseTransformPoint(s.transform.TransformPoint(v));if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}UnityEngine.Object.DestroyImmediate(mesh);}Check(!first,"Missing render bounds");return bounds;}
 static void Studio(){camera=new GameObject("WeaponArtCamera").AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.nearClipPlane=.01f;camera.farClipPlane=30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.045f,.052f,.06f);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.42f,.44f,.46f);
  var cube=new Cubemap(64,TextureFormat.RGBA32,false);for(int f=0;f<6;f++){var px=new Color[4096];for(int y=0;y<64;y++)for(int x=0;x<64;x++)px[y*64+x]=Color.Lerp(new Color(.13f,.15f,.18f),new Color(.85f,.83f,.76f),Mathf.Exp(-Mathf.Pow((x-26)/12f,2))*.8f+(f==2?.12f:0));cube.SetPixels(px,(CubemapFace)f);}cube.Apply();RenderSettings.defaultReflectionMode=UnityEngine.Rendering.DefaultReflectionMode.Custom;RenderSettings.customReflectionTexture=cube;
  var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.15f;key.color=new Color(1,.94f,.87f);key.transform.rotation=Quaternion.Euler(35,145,0);var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.55f;fill.color=new Color(.72f,.82f,1);fill.transform.rotation=Quaternion.Euler(20,-35,0);
 }
 static Material Surface(){foreach(var channel in new[]{"Atlas","Normal","Metallic","Occlusion","Emission"}){var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/RebuiltWeaponTextures/"+channel+".png");Check(importer!=null,"Missing "+channel);importer.maxTextureSize=2048;importer.sRGBTexture=channel=="Atlas"||channel=="Emission";importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.anisoLevel=4;importer.wrapMode=TextureWrapMode.Clamp;importer.alphaSource=TextureImporterAlphaSource.FromInput;if(channel=="Normal")importer.textureType=TextureImporterType.NormalMap;importer.SaveAndReimport();}
  string path="Assets/RebuiltWeaponSurface.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Delve/WeaponRebuildSurface"));AssetDatabase.CreateAsset(mat,path);}mat.shader=Shader.Find("Delve/WeaponRebuildSurface");Check(mat.shader.isSupported,"Weapon shader unsupported");var names=new[]{"Atlas","Normal","Metallic","Occlusion","Emission"};var props=new[]{"_MainTex","_BumpMap","_MetallicGlossMap","_OcclusionMap","_EmissionMap"};for(int i=0;i<names.Length;i++)mat.SetTexture(props[i],AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RebuiltWeaponTextures/"+names[i]+".png"));mat.SetFloat("_BumpScale",.35f);EditorUtility.SetDirty(mat);return mat;
 }
 static void Picture(GameObject obj,string path,int size,Vector3 direction,bool alpha=false,Bounds? fixedBounds=null){var bounds=fixedBounds??BoundsOf(obj);var focus=obj.transform.TransformPoint(bounds.center);camera.orthographicSize=Mathf.Max(.065f,Mathf.Max(bounds.size.y,Mathf.Max(bounds.size.x,bounds.size.z))*.62f);camera.transform.position=focus+direction.normalized*4;camera.transform.LookAt(focus);var background=camera.backgroundColor;if(alpha)camera.backgroundColor=Color.clear;var rt=new RenderTexture(size,size,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var pic=new Texture2D(size,size,alpha?TextureFormat.RGBA32:TextureFormat.RGB24,false);pic.ReadPixels(new Rect(0,0,size,size),0,0);pic.Apply();Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,pic.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;camera.backgroundColor=background;UnityEngine.Object.DestroyImmediate(pic);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 static Transform Find(GameObject obj,string name){return obj.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);}
 static void SaveMesh(Mesh mesh,string path){var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing==null)AssetDatabase.CreateAsset(mesh,path);else{EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);}}
 static void GripCheck(GameObject obj,Spec spec){
  var weapon=Find(obj,"Weapon");var rotation=weapon.localRotation;var position=weapon.localPosition;weapon.localPosition=Vector3.zero;weapon.localRotation=Quaternion.identity;var grip=Find(obj,"GripRight");Check(obj.transform.InverseTransformPoint(grip.position).magnitude<.001f,"Authored grip origin changed "+spec.id);var tip=Find(obj,"EffectOriginSocket");Check((tip.position-grip.position).magnitude>.04f,"Effect socket collapsed "+spec.id);weapon.localRotation=rotation;weapon.localPosition=position;
 }
 static string HeldFixCheck(GameObject prefab,Spec spec){
  bool magic=spec.family=="staff"||spec.family=="hex"||spec.family=="heal"||spec.family=="ward";bool dagger=spec.id=="delveBoneDagger";if(!magic&&!dagger&&spec.family!="spear")return null;
  var native=new GameObject("NativeGripSimulation");var obj=UnityEngine.Object.Instantiate(prefab,native.transform,false);obj.GetComponent<Animator>().enabled=false;if(magic)obj.transform.localRotation=Quaternion.Euler(90,0,0);if(dagger)obj.transform.localScale=Vector3.one*.756f;var weapon=Find(obj,"Weapon");weapon.localPosition=Vector3.zero;weapon.localRotation=Quaternion.identity;var grip=Find(obj,"GripRight");obj.transform.localPosition-=native.transform.InverseTransformPoint(grip.position);if(dagger)obj.transform.localPosition+=new Vector3(0,0,-.017f);var expected=dagger?new Vector3(0,0,-.017f):Vector3.zero;Check((native.transform.InverseTransformPoint(grip.position)-expected).magnitude<.0001f,"Existing native grip correction changed "+spec.id);if(magic)Check(Find(obj,"EffectOriginSocket").position.z>.1f,"Magic focus no longer points forward "+spec.id);string result=spec.id+" current held correction PASS grip="+grip.position+" effect="+Find(obj,"EffectOriginSocket").position;UnityEngine.Object.DestroyImmediate(native);return result;
 }
 static void Process(Spec spec){
  var importer=(ModelImporter)AssetImporter.GetAtPath("Assets/Models/"+spec.id+".fbx");importer.isReadable=true;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.importCameras=false;importer.importLights=false;importer.SaveAndReimport();string pp="Assets/Generated/"+spec.id+".prefab";var obj=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(pp));obj.name=spec.id;var animator=obj.GetComponent<Animator>();animator.enabled=false;var clips=animator.runtimeAnimatorController.animationClips;var skins=obj.GetComponentsInChildren<SkinnedMeshRenderer>(true);Check(skins.Length==3,"LOD count "+spec.id);var bake=new Mesh();int[] triangles=new int[3];
  foreach(string bone in new[]{"Root","Weapon","GripRight","GripLeft","Muzzle","EffectOrigin","EdgeBase","EdgeTip","Focus","LeftWrap","BowUpper","BowLower","String","Ammo"})Check(obj.GetComponentsInChildren<Transform>(true).Any(t=>t.name==bone),"Bone missing "+spec.id+" "+bone);
  foreach(string socket in new[]{"GripRightSocket","GripLeftSocket","MuzzleSocket","EffectOriginSocket","EdgeBaseSocket","EdgeTipSocket"})Check(obj.GetComponentsInChildren<Transform>(true).Any(t=>t.name==socket),"Socket missing");
  for(int i=0;i<3;i++){var skin=skins.Single(s=>s.name=="Weapon_LOD"+i);skin.sharedMaterial=material;var mesh=skin.sharedMesh;triangles[i]=mesh.triangles.Length/3;Check(mesh.tangents.Length==mesh.vertexCount&&mesh.colors.Length==mesh.vertexCount,"Surface channels missing");Check(mesh.boneWeights.All(w=>Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)<.01f),"Skin weights");Check(mesh.uv.All(p=>p.x>.003f&&p.x<.997f&&p.y>.003f&&p.y<.997f),"UV bounds "+spec.id+" LOD"+i+" min="+mesh.uv.Min(p=>Mathf.Min(p.x,p.y))+" max="+mesh.uv.Max(p=>Mathf.Max(p.x,p.y)));skin.updateWhenOffscreen=false;skin.BakeMesh(bake);skin.localBounds=bake.bounds;}
  Check(triangles[0]<24000&&triangles[2]>0&&triangles[2]<triangles[1]&&triangles[1]<triangles[0],"Triangle budget "+spec.id+" "+String.Join("/",triangles));
  foreach(var clip in clips){Check(clip.events.Length==0,"Gameplay animation event");foreach(float t in new[]{0f,.25f,.5f,.75f,.99f}){clip.SampleAnimation(obj,t*clip.length);foreach(var skin in skins){skin.BakeMesh(bake);Check(bake.vertices.All(v=>!float.IsNaN(v.x)&&!float.IsInfinity(v.sqrMagnitude)&&v.sqrMagnitude<25),"Invalid deformation "+spec.id+" "+clip.name);}}}
  clips.First(c=>c.name.EndsWith("Idle")).SampleAnimation(obj,0);GripCheck(obj,spec);var bounds=BoundsOf(obj);Check(bounds.size.magnitude<3,"Model scale "+spec.id);var group=obj.GetComponent<LODGroup>();group.localReferencePoint=bounds.center;group.size=Mathf.Max(bounds.size.y,Mathf.Max(bounds.size.x,bounds.size.z));group.ForceLOD(-1);animator.enabled=true;PrefabUtility.SaveAsPrefabAsset(obj,pp);
  var skin0=skins.Single(s=>s.name=="Weapon_LOD0");skin0.BakeMesh(bake);var dropMesh=UnityEngine.Object.Instantiate(bake);var vertices=dropMesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]=obj.transform.InverseTransformPoint(skin0.transform.TransformPoint(vertices[i]));dropMesh.vertices=vertices;dropMesh.RecalculateBounds();string mp="Assets/Generated/"+spec.id+"_Drop.asset";var dropBounds=dropMesh.bounds;SaveMesh(dropMesh,mp);string dp="Assets/Generated/"+spec.id+"_Drop.prefab";var drop=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(dp));drop.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(mp);drop.GetComponent<MeshRenderer>().sharedMaterial=material;var collider=drop.GetComponent<BoxCollider>();collider.center=dropBounds.center;collider.size=dropBounds.size+Vector3.one*.005f;PrefabUtility.SaveAsPrefabAsset(drop,dp);UnityEngine.Object.DestroyImmediate(drop);
  animator.enabled=false;group.ForceLOD(0);string folder="../Review/"+spec.id;var direction=spec.family=="crossbow"?new Vector3(1.8f,1.3f,1.5f):spec.family=="rune"?new Vector3(.4f,2.5f,1.6f):new Vector3(.75f,.38f,2.7f);Picture(obj,folder+"/hero.png",1024,direction);Picture(obj,folder+"/side.png",768,new Vector3(-1.4f,.25f,2.7f));Picture(obj,folder+"/back.png",768,new Vector3(.6f,.45f,-2.8f));Picture(obj,"../Delivery/UIAtlases/ItemIconAtlas/"+spec.id+".png",256,direction,true);
  if(spec.family!="rune"&&spec.family!="arrow"&&spec.family!="bolt"){
   string state=spec.family=="bow"||spec.family=="crossbow"?"Draw":clips.Any(c=>c.name.EndsWith("Cast"))?"Cast":"LightAttack";var clip=clips.First(c=>c.name.EndsWith(state));for(int i=0;i<8;i++){clip.SampleAnimation(obj,clip.length*i/8);Picture(obj,folder+"/motion-"+i.ToString("D2")+".png",384,direction,false,new Bounds(bounds.center,bounds.size*1.35f));}}
  report.AppendLine(spec.id+" PASS triangles="+String.Join("/",triangles)+" clips="+clips.Length+" LODs=3 weights/tangents/colors/UV=PASS grip/sockets=PASS drop=updated");UnityEngine.Object.DestroyImmediate(bake);UnityEngine.Object.DestroyImmediate(obj);
 }
 static void Bundle(){var paths=Directory.GetFiles("Assets/Generated","*.prefab").OrderBy(p=>p).ToArray();Check(paths.Length==94,"Address contract "+paths.Length);var build=new AssetBundleBuild{assetBundleName="forestweapons.unity3d",assetNames=paths,addressableNames=paths.Select(Path.GetFileNameWithoutExtension).ToArray()};Directory.CreateDirectory("../Bundle");Check(BuildPipeline.BuildAssetBundles("../Bundle",new[]{build},BuildAssetBundleOptions.ChunkBasedCompression|BuildAssetBundleOptions.ForceRebuildAssetBundle,BuildTarget.StandaloneWindows64)!=null,"Bundle failed");File.Copy("../Bundle/forestweapons.unity3d","../Delivery/Resources/forestweapons.unity3d",true);File.WriteAllLines("../Reports/bundle-addresses.txt",build.addressableNames);}
 public static void Run(){try{AssetDatabase.Refresh();Studio();material=Surface();var input=JsonUtility.FromJson<Input>(File.ReadAllText("../weapons.json"));int count=0;foreach(var spec in input.weapons){if(!File.Exists("../Sources/"+spec.id+"/model.json"))continue;File.WriteAllText("../Reports/unity-progress.txt","BUILDING "+spec.id);Process(spec);count++;}AssetDatabase.SaveAssets();bool full=File.Exists("../Reports/build-all.flag");if(full){Check(count==37,"Source coverage");Bundle();}File.WriteAllText("../Reports/unity-validation.txt","PASS models="+count+" full="+full+"\n"+report+"\nLIMIT: offline Unity, no in-game hands-on combat, grip clipping, network or performance certification.");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);File.WriteAllText("../Reports/unity-validation.txt","FAIL\n"+e+"\n"+report);EditorApplication.Exit(1);}}
 public static void Verify(){AssetBundle bundle=null;try{
  bundle=AssetBundle.LoadFromFile(Path.GetFullPath("../Delivery/Resources/forestweapons.unity3d"));Check(bundle!=null,"Delivered bundle reload failed");var addresses=File.ReadAllLines("../Reports/bundle-addresses.txt");Check(bundle.GetAllAssetNames().Length==94&&addresses.Length==94,"Serialized addresses");foreach(var address in addresses){var prefab=bundle.LoadAsset<GameObject>(address);Check(prefab!=null,"Missing address "+address);foreach(var r in prefab.GetComponentsInChildren<Renderer>(true))Check(r.sharedMaterials.All(m=>m!=null&&m.shader!=null),"Missing material "+address);}
  int count=0;var held=new List<string>();var input=JsonUtility.FromJson<Input>(File.ReadAllText("../weapons.json"));foreach(var spec in input.weapons){var prefab=bundle.LoadAsset<GameObject>(spec.id);var obj=UnityEngine.Object.Instantiate(prefab);var animator=obj.GetComponent<Animator>();animator.enabled=false;count+=animator.runtimeAnimatorController.animationClips.Length;foreach(var r in obj.GetComponentsInChildren<SkinnedMeshRenderer>()){Check(r.sharedMaterial.shader.name=="Delve/WeaponRebuildSurface"&&r.sharedMaterial.shader.isSupported,"Serialized shader");foreach(var channel in new[]{"_MainTex","_BumpMap","_MetallicGlossMap","_OcclusionMap","_EmissionMap"})Check(r.sharedMaterial.GetTexture(channel)!=null&&r.sharedMaterial.GetTexture(channel).width==2048,"Serialized map "+spec.id+" "+channel);}Check(obj.GetComponentsInChildren<Collider>(true).Length==0,"Weapon visual gained gameplay collider");GripCheck(obj,spec);UnityEngine.Object.DestroyImmediate(obj);string check=HeldFixCheck(prefab,spec);if(check!=null)held.Add(check);}Check(count==189,"Serialized animation coverage "+count);Check(held.Count==10,"Held correction coverage");File.WriteAllLines("../Reports/held-corrections.txt",held.ToArray());
  foreach(var address in addresses.Where(a=>a.StartsWith("fx"))){var prefab=bundle.LoadAsset<GameObject>(address);var ps=prefab.GetComponent<ParticleSystem>();Check(ps!=null&&ps.main.maxParticles<=128&&!ps.main.loop&&prefab.GetComponentsInChildren<Collider>(true).Length==0,"Effect contract");}
  bundle.Unload(true);File.WriteAllText("../Reports/bundle-validation.txt","PASS exported bundle reloaded; 94 original prefab addresses, 37 rebuilt models, 189 clips, supported materials, grip anchors and 20 bounded existing effects. Offline check only.\nSHA256="+BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes("../Delivery/Resources/forestweapons.unity3d"))).Replace("-","").ToLowerInvariant()+"\n");EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("../Reports/bundle-validation.txt","FAIL\n"+e);if(bundle!=null)bundle.Unload(true);EditorApplication.Exit(1);}}
}
